package com.afkemergency;

import net.runelite.api.Skill;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SkillingActivityTrackerTest
{
    @Test
    public void requiresSupportedExperienceGainAndMatchingAnimation()
    {
        SkillingActivityTracker tracker = new SkillingActivityTracker();
        tracker.onExperience(Skill.FISHING, 1_000, 621, 0);
        assertFalse(tracker.isTrackedAnimation(621, 0));

        tracker.onExperience(Skill.FISHING, 1_010, 621, 1_000);
        assertTrue(tracker.isTrackedAnimation(621, 1_000));
        assertFalse(tracker.isTrackedAnimation(4_840, 1_000));
    }

    @Test
    public void magicTeleportExperienceCannotArmReminder()
    {
        SkillingActivityTracker tracker = new SkillingActivityTracker();
        tracker.onExperience(Skill.MAGIC, 2_000, 4_840, 0);
        tracker.onExperience(Skill.MAGIC, 2_035, 4_840, 1_000);
        assertFalse(tracker.isTrackedAnimation(4_840, 1_000));
    }

    @Test
    public void recognizesMotherlodeWallMiningWithoutExperienceLearning()
    {
        assertTrue(SkillingActivityTracker.isMotherlodeMiningAnimation(
            AnimationID.HUMAN_MINING_RUNE_PICKAXE_WALL));
        assertFalse(SkillingActivityTracker.isMotherlodeMiningAnimation(
            AnimationID.HUMAN_MINING_RUNE_PICKAXE));
        assertFalse(SkillingActivityTracker.isMotherlodeMiningAnimation(-1));
    }
}

package com.afkemergency;

import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class EmergencySoundPlayerTest
{
    @Test
    public void pcmConversionAppliesVolumeWithoutChangingLength()
    {
        short[] samples = {0, 1000, -1000, Short.MAX_VALUE};

        byte[] silent = EmergencySoundPlayer.toPcm(samples, 0.0);
        byte[] half = EmergencySoundPlayer.toPcm(samples, 0.5);

        assertEquals(samples.length * 2, half.length);
        assertArrayEquals(new byte[samples.length * 2], silent);
        assertEquals(500, decode(half, 1));
        assertEquals(-500, decode(half, 2));
    }

    @Test
    public void waveContainerHasHeaderAndPcmPayload()
    {
        byte[] pcm = {1, 2, 3, 4};
        byte[] wave = EmergencySoundPlayer.toWave(pcm);

        assertEquals(48, wave.length);
        assertArrayEquals(new byte[]{'R', 'I', 'F', 'F'},
            new byte[]{wave[0], wave[1], wave[2], wave[3]});
        assertArrayEquals(pcm, new byte[]{wave[44], wave[45], wave[46], wave[47]});
    }

    private static short decode(byte[] pcm, int index)
    {
        return (short) ((pcm[index * 2] & 0xff) | (pcm[index * 2 + 1] << 8));
    }
}

