package com.afkemergency;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AttentionStateTest
{
    @Test
    public void sustainedActivityThenIdleTriggersAlert()
    {
        AttentionState state = new AttentionState();
        assertFalse(state.update(0, true, false, 3_000, 2_000));
        assertFalse(state.update(3_000, true, false, 3_000, 2_000));
        assertFalse(state.update(3_500, false, false, 3_000, 2_000));
        assertTrue(state.update(5_500, false, false, 3_000, 2_000));
        assertTrue(state.isAlerting());
    }

    @Test
    public void shortAnimationDoesNotArmAlert()
    {
        AttentionState state = new AttentionState();
        state.update(0, true, false, 3_000, 1_000);
        state.update(1_000, false, false, 3_000, 1_000);
        assertFalse(state.update(5_000, false, false, 3_000, 1_000));
    }

    @Test
    public void trustedMotherlodeSwingCanArmImmediately()
    {
        AttentionState state = new AttentionState();
        assertFalse(state.update(0, true, false, 0, 2_000));
        assertFalse(state.update(500, false, false, 3_000, 2_000));
        assertTrue(state.update(2_500, false, false, 3_000, 2_000));
    }

    @Test
    public void movementDisarmsPendingAlert()
    {
        AttentionState state = new AttentionState();
        state.update(0, true, false, 3_000, 1_000);
        state.update(3_000, true, false, 3_000, 1_000);
        state.update(3_500, false, true, 3_000, 1_000);
        state.update(4_000, false, false, 3_000, 1_000);
        assertFalse(state.update(8_000, false, false, 3_000, 1_000));
    }

    @Test
    public void clickStartsAndCompletesCelebration()
    {
        AttentionState state = new AttentionState();
        state.showAlert();
        state.dismiss(10_000);
        assertFalse(state.isAlerting());
        assertTrue(state.isCelebrating(10_300, 650));
        assertFalse(state.isCelebrating(10_651, 650));
    }
}

package com.afkemergency;

final class AttentionState
{
    private long activityStartedAt = -1L;
    private long idleStartedAt = -1L;
    private boolean armed;
    private boolean alerting;
    private long celebrationStartedAt = -1L;

    boolean update(long now, boolean animating, boolean moving, long minimumActivityMillis, long idleDelayMillis)
    {
        if (alerting)
        {
            return false;
        }

        if (animating)
        {
            if (activityStartedAt < 0L)
            {
                activityStartedAt = now;
            }
            if (now - activityStartedAt >= minimumActivityMillis)
            {
                armed = true;
            }
            idleStartedAt = -1L;
            return false;
        }

        activityStartedAt = -1L;
        if (!armed || moving)
        {
            if (moving)
            {
                armed = false;
            }
            idleStartedAt = -1L;
            return false;
        }

        if (idleStartedAt < 0L)
        {
            idleStartedAt = now;
        }

        if (now - idleStartedAt >= idleDelayMillis)
        {
            alerting = true;
            armed = false;
            idleStartedAt = -1L;
            return true;
        }
        return false;
    }

    void showAlert()
    {
        alerting = true;
        celebrationStartedAt = -1L;
    }

    void dismiss(long now)
    {
        if (alerting)
        {
            alerting = false;
            celebrationStartedAt = now;
        }
        armed = false;
        activityStartedAt = -1L;
        idleStartedAt = -1L;
    }

    void reset()
    {
        activityStartedAt = -1L;
        idleStartedAt = -1L;
        celebrationStartedAt = -1L;
        armed = false;
        alerting = false;
    }

    boolean isAlerting()
    {
        return alerting;
    }

    boolean isCelebrating(long now, long durationMillis)
    {
        if (celebrationStartedAt < 0L)
        {
            return false;
        }
        if (now - celebrationStartedAt >= durationMillis)
        {
            celebrationStartedAt = -1L;
            return false;
        }
        return true;
    }

    long getCelebrationStartedAt()
    {
        return celebrationStartedAt;
    }
}

package com.afkemergency;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(AfkEmergencyConfig.GROUP)
public interface AfkEmergencyConfig extends Config
{
    String GROUP = "afkEmergency";

    @ConfigItem(
        keyName = "minimumActivitySeconds",
        name = "Activity time",
        description = "How long a verified skilling animation must continue before the reminder is armed",
        position = 0
    )
    @Range(min = 1, max = 30)
    @Units(Units.SECONDS)
    default int minimumActivitySeconds()
    {
        return 3;
    }

    @ConfigItem(
        keyName = "idleDelaySeconds",
        name = "Grace period",
        description = "How long to wait after the action stops before showing the button",
        position = 1
    )
    @Range(min = 0, max = 30)
    @Units(Units.SECONDS)
    default int idleDelaySeconds()
    {
        return 2;
    }

    @ConfigItem(
        keyName = "dimOpacity",
        name = "Screen dimming",
        description = "How strongly the rest of the game is dimmed",
        position = 2
    )
    @Range(min = 0, max = 90)
    @Units(Units.PERCENT)
    default int dimOpacity()
    {
        return 62;
    }

    @ConfigItem(
        keyName = "dismissAnywhere",
        name = "Any click dismisses",
        description = "Dismiss on any game click. The dismissing click is blocked for safety",
        position = 3
    )
    default boolean dismissAnywhere()
    {
        return true;
    }

    @ConfigItem(
        keyName = "previewHotkey",
        name = "Preview hotkey",
        description = "A hotkey for previewing the alert and its dismissal animation",
        position = 4
    )
    default Keybind previewHotkey()
    {
        return Keybind.NOT_SET;
    }

    @ConfigItem(
        keyName = "alertSound",
        name = "Alert sound",
        description = "Play a gentle chime when the emergency button appears",
        position = 5
    )
    default boolean alertSound()
    {
        return true;
    }

    @ConfigItem(
        keyName = "pressSound",
        name = "Button press sound",
        description = "Play a short pop when the alert is dismissed",
        position = 6
    )
    default boolean pressSound()
    {
        return true;
    }

    @ConfigItem(
        keyName = "soundVolume",
        name = "Sound volume",
        description = "Volume of the alert and button press sounds",
        position = 7
    )
    @Range(min = 0, max = 100)
    @Units(Units.PERCENT)
    default int soundVolume()
    {
        return 35;
    }
}

package com.afkemergency;

import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Station's AFK Button",
    description = "Flashes a big red attention button when a sustained skilling action stops",
    tags = {"afk", "idle", "notification", "skilling", "accessibility", "adhd"}
)
public class AfkEmergencyPlugin extends Plugin
{
    static final long CELEBRATION_MILLIS = 240L;

    @Inject private Client client;
    @Inject private AfkEmergencyConfig config;
    @Inject private AfkEmergencyOverlay overlay;
    @Inject private AfkEmergencyDimOverlay dimOverlay;
    @Inject private OverlayManager overlayManager;
    @Inject private MouseManager mouseManager;
    @Inject private KeyManager keyManager;
    @Inject private EmergencySoundPlayer soundPlayer;

    private final AttentionState state = new AttentionState();
    private final SkillingActivityTracker skillingActivity = new SkillingActivityTracker();
    private final MouseListener mouseListener = new MouseListener()
    {
        @Override
        public MouseEvent mousePressed(MouseEvent event)
        {
            if (state.isAlerting() && (config.dismissAnywhere() || overlay.contains(event.getPoint())))
            {
                event.consume();
                state.dismiss(System.currentTimeMillis());
                skillingActivity.clearAnimation();
                if (config.pressSound())
                {
                    soundPlayer.playPress(config.soundVolume());
                }
            }
            return event;
        }

        @Override public MouseEvent mouseReleased(MouseEvent event) { return event; }
        @Override public MouseEvent mouseClicked(MouseEvent event) { return event; }
        @Override public MouseEvent mouseEntered(MouseEvent event) { return event; }
        @Override public MouseEvent mouseExited(MouseEvent event) { return event; }
        @Override public MouseEvent mouseDragged(MouseEvent event) { return event; }
        @Override public MouseEvent mouseMoved(MouseEvent event) { return event; }
    };
    private final KeyListener keyListener = new KeyListener()
    {
        @Override
        public void keyPressed(KeyEvent event)
        {
            if (config.previewHotkey().matches(event) && !state.isAlerting())
            {
                state.showAlert();
                playAlertSound();
            }
        }

        @Override public void keyReleased(KeyEvent event) { }
        @Override public void keyTyped(KeyEvent event) { }
    };

    @Provides
    AfkEmergencyConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(AfkEmergencyConfig.class);
    }

    @Override
    protected void startUp()
    {
        state.reset();
        skillingActivity.reset();
        soundPlayer.startUp();
        overlayManager.add(dimOverlay);
        overlayManager.add(overlay);
        mouseManager.registerMouseListener(mouseListener);
        keyManager.registerKeyListener(keyListener);
    }

    @Override
    protected void shutDown()
    {
        keyManager.unregisterKeyListener(keyListener);
        mouseManager.unregisterMouseListener(mouseListener);
        overlayManager.remove(overlay);
        overlayManager.remove(dimOverlay);
        soundPlayer.shutDown();
        state.reset();
        skillingActivity.reset();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            state.reset();
            skillingActivity.reset();
            return;
        }

        Player player = client.getLocalPlayer();
        if (player == null)
        {
            state.reset();
            skillingActivity.reset();
            return;
        }

        long now = System.currentTimeMillis();
        int animation = player.getAnimation();
        boolean motherlodeMining = SkillingActivityTracker.isMotherlodeMiningAnimation(animation);
        boolean animating = motherlodeMining || skillingActivity.isTrackedAnimation(animation, now);
        boolean moving = player.getPoseAnimation() != player.getIdlePoseAnimation();
        if (animation != -1 && !animating)
        {
            state.update(now, false, true,
                config.minimumActivitySeconds() * 1000L,
                config.idleDelaySeconds() * 1000L);
            skillingActivity.clearAnimation();
            return;
        }
        boolean alertStarted = state.update(
            now,
            animating,
            moving,
            motherlodeMining ? 0L : config.minimumActivitySeconds() * 1000L,
            config.idleDelaySeconds() * 1000L
        );
        if (alertStarted)
        {
            playAlertSound();
        }
        if (moving)
        {
            skillingActivity.clearAnimation();
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        Player player = client.getLocalPlayer();
        int animation = player == null ? -1 : player.getAnimation();
        skillingActivity.onExperience(
            event.getSkill(), event.getXp(), animation, System.currentTimeMillis());
    }

    boolean isAlerting()
    {
        return state.isAlerting();
    }

    boolean isCelebrating(long now)
    {
        return state.isCelebrating(now, CELEBRATION_MILLIS);
    }

    long getCelebrationStartedAt()
    {
        return state.getCelebrationStartedAt();
    }

    private void playAlertSound()
    {
        if (config.alertSound())
        {
            soundPlayer.playAlert(config.soundVolume());
        }
    }
}

package com.afkemergency;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

final class AfkEmergencyOverlay extends Overlay
{
    private static final int PREFERRED_WIDTH = 360;
    private static final int PREFERRED_HEIGHT = 380;
    private static final int LABEL_HEIGHT = 30;
    private static final int SOURCE_WIDTH = 240;
    private static final int SOURCE_HEIGHT = 230;
    private static final BufferedImage[] BUTTON_FRAMES = loadFrames();

    private final AfkEmergencyPlugin plugin;

    @Inject
    private AfkEmergencyOverlay(AfkEmergencyPlugin plugin)
    {
        super(plugin);
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(OverlayPriority.HIGHEST);
        setResizable(true);
        setMinimumSize(120);
        setPreferredSize(new Dimension(PREFERRED_WIDTH, PREFERRED_HEIGHT));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        long now = System.currentTimeMillis();
        boolean alerting = plugin.isAlerting();
        boolean celebrating = plugin.isCelebrating(now);
        if (!alerting && !celebrating)
        {
            return null;
        }

        double progress = celebrating
            ? Math.min(1.0, (now - plugin.getCelebrationStartedAt())
                / (double) AfkEmergencyPlugin.CELEBRATION_MILLIS)
            : 0.0;
        int frameIndex = alerting ? 0 : Math.min(7, 1 + (int) (progress * 7.0));

        Dimension available = getPreferredSize() == null
            ? new Dimension(PREFERRED_WIDTH, PREFERRED_HEIGHT) : getPreferredSize();
        int contentHeight = Math.max(1, available.height - LABEL_HEIGHT);
        double scale = Math.min(available.width / (double) SOURCE_WIDTH,
            contentHeight / (double) SOURCE_HEIGHT);
        int width = Math.max(1, (int) Math.round(SOURCE_WIDTH * scale));
        int height = Math.max(1, (int) Math.round(SOURCE_HEIGHT * scale));
        int x = (available.width - width) / 2;
        int y = LABEL_HEIGHT + (contentHeight - height) / 2;

        Object oldInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        graphics.drawImage(BUTTON_FRAMES[frameIndex], x, y, width, height, null);
        if (oldInterpolation != null)
        {
            graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
        }

        if (alerting)
        {
            String label = available.width < 280 ? "AFK!" : "AFK EMERGENCY - CLICK TO RESUME";
            drawCentered(graphics, label, 22, available.width);
        }
        return available;
    }

    boolean contains(Point point)
    {
        return getBounds().contains(point);
    }

    private static void drawCentered(Graphics2D graphics, String text, int baseline, int width)
    {
        graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
            RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        int fontSize = Math.max(11, Math.min(20, width / 18));
        graphics.setFont(new Font("SansSerif", Font.BOLD, fontSize));
        FontMetrics metrics = graphics.getFontMetrics();
        int x = (width - metrics.stringWidth(text)) / 2;
        graphics.setColor(new Color(0, 0, 0, 190));
        graphics.drawString(text, x + 2, baseline + 2);
        graphics.setColor(new Color(255, 225, 171));
        graphics.drawString(text, x, baseline);
    }

    private static BufferedImage[] loadFrames()
    {
        BufferedImage[] frames = new BufferedImage[8];
        for (int frame = 0; frame < frames.length; frame++)
        {
            String resource = "/com/afkemergency/emergency-button-" + frame + ".png";
            try (InputStream input = AfkEmergencyOverlay.class.getResourceAsStream(resource))
            {
                if (input == null)
                {
                    throw new IllegalStateException("Missing emergency button sprite " + resource);
                }
                frames[frame] = ImageIO.read(input);
            }
            catch (IOException ex)
            {
                throw new IllegalStateException("Unable to load emergency button sprite " + resource, ex);
            }
        }
        return frames;
    }
}

package com.afkemergency;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.AnimationID;

final class SkillingActivityTracker
{
    private static final long MAX_TRACKED_AGE_MILLIS = 60_000L;
    private static final EnumSet<Skill> SUPPORTED_SKILLS = EnumSet.of(
        Skill.AGILITY, Skill.CONSTRUCTION, Skill.COOKING, Skill.CRAFTING,
        Skill.FARMING, Skill.FIREMAKING, Skill.FISHING, Skill.FLETCHING,
        Skill.HERBLORE, Skill.HUNTER, Skill.MINING, Skill.RUNECRAFT,
        Skill.SMITHING, Skill.THIEVING, Skill.WOODCUTTING
    );

    private final Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
    private int trackedAnimation = -1;
    private long trackedAt = -1L;

    void onExperience(Skill skill, int xp, int animation, long now)
    {
        Integer previous = experience.put(skill, xp);
        if (previous != null && xp > previous && animation != -1 && isSupportedSkill(skill))
        {
            trackedAnimation = animation;
            trackedAt = now;
        }
    }

    boolean isTrackedAnimation(int animation, long now)
    {
        boolean tracked = animation != -1 && animation == trackedAnimation
            && trackedAt >= 0L && now - trackedAt <= MAX_TRACKED_AGE_MILLIS;
        if (tracked)
        {
            trackedAt = now;
        }
        return tracked;
    }

    static boolean isMotherlodeMiningAnimation(int animation)
    {
        switch (animation)
        {
            case AnimationID.HUMAN_MINING_BRONZE_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_IRON_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_STEEL_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_BLACK_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_MITHRIL_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_ADAMANT_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_RUNE_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_GILDED_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_DRAGON_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_DRAGON_PICKAXE_PRETTY_WALL:
            case AnimationID.HUMAN_MINING_ZALCANO_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_TRAILBLAZER_PICKAXE_NO_INFERNAL_WALL:
            case AnimationID.HUMAN_MINING_INFERNAL_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_TRAILBLAZER_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_TRAILBLAZER_RELOADED_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_3A_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_CRYSTAL_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_LEAGUE_TRAILBLAZER_PICKAXE_WALL:
            case AnimationID.HUMAN_MINING_TRAILBLAZER_RELOADED_PICKAXE_NO_INFERNAL_WALL:
                return true;
            default:
                return false;
        }
    }

    void clearAnimation()
    {
        trackedAnimation = -1;
        trackedAt = -1L;
    }

    void reset()
    {
        experience.clear();
        clearAnimation();
    }

    static boolean isSupportedSkill(Skill skill)
    {
        return SUPPORTED_SKILLS.contains(skill);
    }
}

package com.afkemergency;

import java.io.ByteArrayInputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.audio.AudioPlayer;

@Singleton
final class EmergencySoundPlayer
{
    private static final float SAMPLE_RATE = 44_100F;
    private static final short[] ALERT = createAlert();
    private static final short[] PRESS = createPress();

    private final AudioPlayer audioPlayer;
    private ExecutorService executor;

    @Inject
    private EmergencySoundPlayer(AudioPlayer audioPlayer)
    {
        this.audioPlayer = audioPlayer;
    }

    synchronized void startUp()
    {
        if (executor == null || executor.isShutdown())
        {
            executor = Executors.newSingleThreadExecutor(task ->
            {
                Thread thread = new Thread(task, "afk-emergency-sound");
                thread.setDaemon(true);
                return thread;
            });
        }
    }

    synchronized void shutDown()
    {
        if (executor != null)
        {
            executor.shutdownNow();
            executor = null;
        }
    }

    void playAlert(int volume)
    {
        play(ALERT, volume);
    }

    void playPress(int volume)
    {
        play(PRESS, volume);
    }

    private synchronized void play(short[] samples, int volume)
    {
        if (executor == null || volume <= 0)
        {
            return;
        }

        int clamped = Math.min(100, volume);
        double gain = Math.pow(clamped / 100.0, 1.45);
        byte[] pcm = toPcm(samples, gain);
        try
        {
            executor.execute(() -> output(toWave(pcm)));
        }
        catch (RejectedExecutionException ignored)
        {
            // The plugin was disabled between scheduling and playback.
        }
    }

    private void output(byte[] wave)
    {
        try (ByteArrayInputStream input = new ByteArrayInputStream(wave))
        {
            audioPlayer.play(input, 0F);
        }
        catch (Exception ignored)
        {
            // Audio is optional; a missing output device must never affect the alert.
        }
    }

    static byte[] toWave(byte[] pcm)
    {
        ByteBuffer wave = ByteBuffer.allocate(44 + pcm.length).order(ByteOrder.LITTLE_ENDIAN);
        wave.put("RIFF".getBytes(StandardCharsets.US_ASCII));
        wave.putInt(36 + pcm.length);
        wave.put("WAVE".getBytes(StandardCharsets.US_ASCII));
        wave.put("fmt ".getBytes(StandardCharsets.US_ASCII));
        wave.putInt(16);
        wave.putShort((short) 1);
        wave.putShort((short) 1);
        wave.putInt((int) SAMPLE_RATE);
        wave.putInt((int) SAMPLE_RATE * 2);
        wave.putShort((short) 2);
        wave.putShort((short) 16);
        wave.put("data".getBytes(StandardCharsets.US_ASCII));
        wave.putInt(pcm.length);
        wave.put(pcm);
        return wave.array();
    }

    static byte[] toPcm(short[] samples, double gain)
    {
        byte[] pcm = new byte[samples.length * 2];
        for (int i = 0; i < samples.length; i++)
        {
            int value = (int) Math.round(samples[i] * gain);
            value = Math.max(Short.MIN_VALUE, Math.min(Short.MAX_VALUE, value));
            pcm[i * 2] = (byte) value;
            pcm[i * 2 + 1] = (byte) (value >>> 8);
        }
        return pcm;
    }

    private static short[] createAlert()
    {
        int count = millisecondsToSamples(310);
        short[] samples = new short[count];
        for (int i = 0; i < count; i++)
        {
            double time = i / SAMPLE_RATE;
            double attack = Math.min(1.0, time / 0.025);
            double release = Math.pow(Math.max(0.0, 1.0 - time / 0.31), 1.7);
            double first = Math.sin(2.0 * Math.PI * 523.25 * time);
            double second = Math.sin(2.0 * Math.PI * 659.25 * time);
            double warmth = Math.sin(2.0 * Math.PI * 261.63 * time);
            samples[i] = asSample((first * 0.42 + second * 0.38 + warmth * 0.20)
                * attack * release * 0.32);
        }
        return samples;
    }

    private static short[] createPress()
    {
        int count = millisecondsToSamples(52);
        short[] samples = new short[count];
        long noise = 0x51F15EEDL;
        double previousNoise = 0.0;
        for (int i = 0; i < count; i++)
        {
            double time = i / SAMPLE_RATE;
            noise = (noise * 1_103_515_245L + 12_345L) & 0x7fffffffL;
            double texture = (noise / (double) 0x7fffffffL) * 2.0 - 1.0;
            double highPassedNoise = texture - previousNoise;
            previousNoise = texture;

            double contact = highPassedNoise * Math.exp(-time * 520.0);
            double shell = (Math.sin(2.0 * Math.PI * 2_350.0 * time) * 0.58
                + Math.sin(2.0 * Math.PI * 3_700.0 * time) * 0.42)
                * Math.exp(-time * 260.0);

            double releaseTime = time - 0.024;
            double releaseClick = releaseTime >= 0.0
                ? (Math.sin(2.0 * Math.PI * 2_050.0 * releaseTime) * 0.65
                    + Math.sin(2.0 * Math.PI * 3_250.0 * releaseTime) * 0.35)
                    * Math.exp(-releaseTime * 330.0)
                : 0.0;

            samples[i] = asSample((contact * 0.48 + shell * 0.72
                + releaseClick * 0.34) * 0.46);
        }
        return samples;
    }

    private static int millisecondsToSamples(int milliseconds)
    {
        return Math.round(SAMPLE_RATE * milliseconds / 1000F);
    }

    private static short asSample(double value)
    {
        return (short) Math.round(Math.max(-1.0, Math.min(1.0, value)) * Short.MAX_VALUE);
    }
}

package com.afkemergency;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

final class AfkEmergencyDimOverlay extends Overlay
{
    private final Client client;
    private final AfkEmergencyPlugin plugin;
    private final AfkEmergencyConfig config;

    @Inject
    private AfkEmergencyDimOverlay(Client client, AfkEmergencyPlugin plugin, AfkEmergencyConfig config)
    {
        super(plugin);
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isAlerting())
        {
            return null;
        }
        int width = client.getCanvasWidth();
        int height = client.getCanvasHeight();
        int alpha = Math.round(255 * config.dimOpacity() / 100f);
        graphics.setColor(new Color(0, 0, 0, alpha));
        graphics.fillRect(0, 0, width, height);
        return new Dimension(width, height);
    }
}
